// Conjugeur service worker: precache everything, serve cache-first.
// VERSION and PRECACHE are generated by `npm run sw` (tools/build-sw.mjs);
// do not edit them by hand. tests/sw.test.js fails when they are stale.

// <generated>
const VERSION = '130acfa6d54b';
const PRECACHE = [
  './',
  'css/app.css',
  'fonts/OFL.txt',
  'fonts/chivo-latin-wght.woff2',
  'icons/apple-touch-icon.png',
  'icons/icon-192.png',
  'icons/icon-512.png',
  'icons/icon-maskable-512.png',
  'index.html',
  'js/core/checker.js',
  'js/core/conjugator.js',
  'js/core/french.js',
  'js/core/generator.js',
  'js/core/scheduler.js',
  'js/core/store.js',
  'js/data/complements.js',
  'js/data/forms.js',
  'js/data/frames.js',
  'js/data/subjects.js',
  'js/data/verbs.js',
  'js/main.js',
  'js/sw-register.js',
  'js/ui/dom.js',
  'js/ui/practice.js',
  'js/ui/progress.js',
  'js/ui/settings.js',
  'js/ui/strings.js',
  'manifest.webmanifest',
];
// </generated>

const CACHE = `conjugeur-${VERSION}`;
// All URLs resolve against the worker's scope so the app works under a sub-path.
const url = (path) => new URL(path, self.registration.scope).href;

self.addEventListener('install', (event) => {
  // No skipWaiting() here: an update waits until the page asks for it.
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      cache.addAll(PRECACHE.map((p) => new Request(url(p), { cache: 'reload' })))),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys
        .filter((k) => k.startsWith('conjugeur-') && k !== CACHE)
        .map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  const isNav = req.mode === 'navigate';
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: isNav });
    if (hit) return hit;
    if (isNav) {
      const shell = await cache.match(url('index.html'));
      if (shell) return shell;
    }
    // Cache miss: network only. Nothing new is written to the cache, so opaque
    // or cross-origin responses can never end up in it.
    return fetch(req);
  })());
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});
